import{GARDEN_CONFIG as u}from"./config.min.js";import{seasonAt as p,wrapHour as m,clamp01 as c}from"./clock.min.js";export const STATES=["sunny","cloudy","windy","stormy"];export function weightsFor(t,n=u){return n.weather.weights[t]||n.weather.weights.summer}export function nextState(t,n,e,o=u){const s=weightsFor(n,o);let r=0;for(const a of STATES)a!==t&&(r+=s[a]||0);if(r<=0)return t;let i=0;const l=c(e)*r;for(const a of STATES)if(a!==t&&(i+=s[a]||0,l<=i))return a;return STATES[STATES.length-1]===t?STATES[0]:STATES[STATES.length-1]}export function dwellFor(t,n=u){const e=n.weather.dwell;return e.min+c(t)*(e.max-e.min)}export function temperatureAt(t,n=u){const e=n.weather.temperature,o=(Math.sin((m(t)-6)*Math.PI/12)+1)/2;return e.coldest+(e.warmest-e.coldest)*o}export function precipFor(t,n,e=u){if(t<=.01)return"none";const o=e.weather.temperature,s=temperatureAt(n,e);return s<o.snowBelow?"snow":s<o.sleetBelow?"sleet":"rain"}export function gustAt(t,n=u){const e=n.weather.gust;let o=0;for(let r=0;r<e.periods.length;r++)o+=e.weights[r]*Math.sin(t*Math.PI*2/e.periods[r]+r*1.7+r*r*.7);const s=Math.pow(c((o+1)/2),e.shape);return e.floor+(e.peak-e.floor)*s}export function blendStates(t,n,e,o=u){const s=o.weather.states[t],r=o.weather.states[n],i=l=>s[l]+(r[l]-s[l])*c(e);return{gloom:i("gloom"),wind:i("wind"),rain:i("rain")}}export function createWeather(t="sunny"){return{state:t,from:t,transition:1,held:0,dwell:30,angle:.8,gloom:0,windStrength:0,gust:1,rain:0,wind:{x:0,z:0},precip:"none"}}export function stepWeather(t,n,e,o=0,s=Math.random,r=!1,i=u){const l=i.weather,a=r?l.reducedTransitionSeconds:l.transitionSeconds;t.transition<1?t.transition=Math.min(1,t.transition+n/a):(t.held+=n,t.held>=t.dwell&&(t.from=t.state,t.state=nextState(t.state,p(e),s(),i),t.dwell=dwellFor(s(),i),t.held=0,t.transition=0));const h=blendStates(t.from,t.state,t.transition,i);t.gloom=h.gloom,t.rain=h.rain;const d=gustAt(o,i);return t.gust=r?1+(d-1)*l.gust.reducedDamp:d,t.windStrength=h.wind*t.gust,t.angle+=l.turnRate*n*(r?.4:1),t.wind.x=Math.cos(t.angle)*t.windStrength,t.wind.z=Math.sin(t.angle)*t.windStrength,t.precip=precipFor(t.rain,e,i),t}export function weatherWords(t,n=null,e=u){const o=e.weather,s=o.precipitation.visibleRate,r=n&&n.rain>=s,i=n&&n.snow>=s,l=(t.windStrength||0)>=o.windyAbove;let a="";return r&&i?a="sleet":i?a="snow":r&&(a="rain"),a?l?`windy ${a}`:a:l?"windy":t.gloom>o.cloudyAbove?"cloudy":"clear"}
